import React, { useImperativeHandle, useRef, useState } from 'react';

import { omitTransientProps } from 'utils/emotion';

import {
  StyledClearButton,
  StyledClearIcon,
  StyledInputContainer,
  StyledInputWrapper,
  StyledSearchIcon,
  StyledWrapper,
} from '../SearchField.styles';
import type {
  SearchFieldRootProps,
  SearchFieldRootRef,
} from '../SearchField.types';

export const SearchFieldRoot = React.forwardRef<
  SearchFieldRootRef,
  SearchFieldRootProps
>(
  (
    {
      size = 'medium',
      children,
      width,
      onClear,
      onSearch,
      defaultValue,
      value: valueFromProps,
      required = true,
      placeholder = 'Search',
      className,
      disabled = false,
      onChange,
      label,
      ...props
    },
    forwardedRef,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const searchIconRef = useRef<SVGSVGElement>(null);
    const inputWrapperRef = useRef<HTMLDivElement>(null);

    const hasDefaultValue = defaultValue !== undefined;
    const isControlled = valueFromProps !== undefined;
    const [value, setValue] = useState<string>(
      hasDefaultValue ? String(defaultValue) : '',
    );
    const mappedValue = isControlled ? String(valueFromProps) : value;

    useImperativeHandle(
      forwardedRef,
      () => inputRef.current as HTMLInputElement,
    );

    const handleWrapperFocus = (event: React.MouseEvent<HTMLDivElement>) => {
      const isWrapper = event.target === containerRef.current;
      const isSearchIcon = event.target === searchIconRef.current;
      const isInputWrapper = event.target === inputWrapperRef.current;

      if (
        inputRef.current &&
        (isWrapper || isSearchIcon || isInputWrapper) &&
        !disabled
      ) {
        inputRef.current.focus();
      }
    };

    const handleClear = (event: React.MouseEvent<HTMLButtonElement>) => {
      if (!isControlled) {
        setValue('');
      }
      onClear?.(event);
      inputRef.current?.focus();
    };

    const handleChange = (event: React.FormEvent<HTMLInputElement>) => {
      onChange?.(event);
      if (!isControlled) {
        setValue(event.currentTarget.value);
      }
    };

    const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
      props.onKeyDown?.(event);

      if (event.key === 'Enter' && onSearch) {
        onSearch(mappedValue, event);
      }
    };

    return (
      <StyledWrapper
        ref={containerRef}
        className={className}
        $disabled={disabled}
        $size={size}
        $width={width}
        data-testid="search-field-wrapper"
        onClick={handleWrapperFocus}
      >
        {children}
        <StyledInputWrapper ref={inputWrapperRef}>
          <StyledSearchIcon
            ref={searchIconRef}
            className="search-icon"
            disabled={disabled}
            size="large"
          />
          <StyledInputContainer $size={size}>
            <input
              {...omitTransientProps(props)}
              ref={inputRef}
              aria-label={label}
              disabled={disabled}
              onChange={handleChange}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              required={required}
              type="text"
              value={mappedValue}
            />
          </StyledInputContainer>
          <StyledClearButton
            aria-hidden={!mappedValue}
            aria-label={`Clear ${label || 'input'}`}
            disabled={disabled}
            type="button"
            $isVisible={Boolean(mappedValue)}
            onClick={handleClear}
          >
            <StyledClearIcon size="tiny" />
          </StyledClearButton>
        </StyledInputWrapper>
      </StyledWrapper>
    );
  },
);

SearchFieldRoot.displayName = 'SearchField.Root';
